                    getPersonnelAssignedToVehicle(
                        personnel,
                        vehicle
                    );
                const qualified =
                    assigned.filter(
                        person =>
                            personnelMatchesRule(
                                person,
                                rule
                            )
                    ).length;
                const total = assigned.length;
                const capacity =
                    Math.max(
                        rule.target,
                        Number(vehicle.maxCount)
                        || rule.target
                    );
